/* The month to build. Defaults to the PREVIOUS calendar month, because the run
   happens on the 2nd and builds the month that just closed. Override by setting
   the n8n variable RBL_MONTH (format YYYY-MM) for a re-run of an older month. */
const override = $vars.RBL_MONTH;
let month = override;
if (!month) {
  const d = new Date();
  d.setUTCDate(1);
  d.setUTCMonth(d.getUTCMonth() - 1);
  month = d.toISOString().slice(0, 7);
}
if (!/^\d{4}-\d{2}$/.test(month)) throw new Error(`RBL_MONTH must be YYYY-MM, got ${JSON.stringify(month)}`);
/* A runId, because the month lock is per-run: releasing one you cannot prove
   is yours would leave two writers on one month, and lock.mjs refuses to. */
const runId = 'rbl-month-' + new Date().toISOString().replace(/[:.]/g, '-');

/* Published so the Error Handler can find the month and runId on a crash — it
   is handed the failing execution, not our data. Wrapped because customData is
   not available in every execution mode and its absence must not be the thing
   that fails the run. */
try {
  $execution.customData.set('month', month);
  $execution.customData.set('runId', runId);
} catch (e) { /* not available in this mode; the handler falls back */ }

return [{ json: { month, runId, startedAt: new Date().toISOString() } }];

/* Shared parse. Every stage prints exactly one line of JSON last, then an
   __EXIT__<code> marker. Exit codes: 0 = done · 10 = deliberate stop, needs a
   human · anything else = crash.

   The marker exists so a deliberate stop does not surface as a red node. A stop
   is information, not a fault — only a crash should look like one. */
const STAGE = '00 Preflight';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
let r;
try { r = JSON.parse(jsonLine); }
catch (e) { throw new Error(`${STAGE} JSON did not parse (exit ${exitCode}): ${e.message}\n` + jsonLine.slice(0, 600)); }
if (exitCode !== 0 && exitCode !== 10) throw new Error(`${STAGE} failed (exit ${exitCode}): ${r.error || 'no error field'}\n--- tail ---\n` + raw.slice(-1200));
return [{ json: { ...r, exitCode, month: $('Resolve month').first().json.month } }];

const STAGE = '01 Fetch';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
let r;
try { r = JSON.parse(jsonLine); }
catch (e) { throw new Error(`${STAGE} JSON did not parse (exit ${exitCode}): ${e.message}\n` + jsonLine.slice(0, 600)); }
if (exitCode !== 0 && exitCode !== 10) throw new Error(`${STAGE} failed (exit ${exitCode}): ${r.error || 'no error field'}\n--- tail ---\n` + raw.slice(-1200));
if (!r.books || r.books === 0) throw new Error('01 Fetch found no books. Check S3_PREFIX_BOOKS and that the month has actually been delivered.');
return [{ json: { ...r, exitCode, month: $('Resolve month').first().json.month } }];

const STAGE = '02 Plan';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
let r;
try { r = JSON.parse(jsonLine); }
catch (e) { throw new Error(`${STAGE} JSON did not parse (exit ${exitCode}): ${e.message}\n` + jsonLine.slice(0, 600)); }
if (exitCode !== 0 && exitCode !== 10) throw new Error(`${STAGE} failed (exit ${exitCode}): ${r.error || 'no error field'}\n--- tail ---\n` + raw.slice(-1200));

/* A planner warning is a stop-and-ask, never a log line. In July these would have
   caught two books both named "CYC 12 PDD+7" that differed only by load date
   (95 accounts vs 1,296), and the PDD+11/+12 family that had no verified day count. */
const needsHuman = exitCode === 10 || !!(r.warnings || []).length || !!(r.unassigned || []).length;
return [{ json: { ...r, exitCode, needsHuman, month: $('Resolve month').first().json.month } }];

const STAGE = '03a List cohorts';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
const r = JSON.parse(jsonLine);
if (exitCode !== 0) throw new Error(`${STAGE} failed (exit ${exitCode}): ${r.error || ''}`);

const month = $('Resolve month').first().json.month;
const pending = (r.cohorts || []).filter(c => !c.collected);
if (!pending.length) return [{ json: { month, key: null, empty: true } }];

/* One item per cohort. The loop below runs them one at a time — Convin enforces a
   global per-tenant lock, so parallelism is not available even if it were wanted.
   The upside of looping in n8n rather than inside the script: each cohort shows as
   its own row in the execution view, so a stall is visible while it is happening. */
return pending.map(c => ({ json: { ...c, month } }));

const STAGE = '03b Export';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
const r = JSON.parse(jsonLine);

/* A failed or hung export means RETRY — never "no calls". In August two consecutive
   failures looked like calling had stopped; the retries returned 8,250 and 9,044
   rows of real activity. If the script has exhausted its retries, stop the month
   rather than letting an empty cohort through. */
if (exitCode !== 0) throw new Error(`${STAGE} exhausted retries for cohort ${r.key || '?'} (exit ${exitCode}): ${r.error || 'no error field'}\nDo NOT treat this as "no calls" — re-run the workflow once Convin's queue is healthy.`);
if (r.rows === 0) throw new Error(`${STAGE} returned 0 rows for cohort ${r.key}. Verify against the campaign UI before accepting — this pattern has been a queue failure every time it has appeared.`);
return [{ json: r }];

const STAGE = '04 Collect';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
const r = JSON.parse(jsonLine);
if (exitCode !== 0) throw new Error(`${STAGE} failed for cohort ${r.key || '?'} (exit ${exitCode}): ${r.error || 'no error field'}\n--- tail ---\n` + raw.slice(-1200));

/* Cohort account count must equal the sum of the books loaded that day, exactly.
   That check held 21 times out of 21 across both July campaigns — it is the
   strongest single assertion available anywhere in this pipeline. */
if (r.expectedAccounts != null && r.accounts !== r.expectedAccounts) {
  throw new Error(`${STAGE} cohort ${r.key}: ${r.accounts} accounts but the books loaded that day sum to ${r.expectedAccounts}. The lead filter did not apply cleanly, or a book is missing.`);
}
return [{ json: r }];

const STAGE = '05 Assemble';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
const r = JSON.parse(jsonLine);
if (exitCode !== 0 && exitCode !== 10) throw new Error(`${STAGE} failed (exit ${exitCode}): ${r.error || 'no error field'}\n--- tail ---\n` + raw.slice(-1200));
return [{ json: { ...r, month: $('Resolve month').first().json.month } }];

const STAGE = '06 Build';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
const r = JSON.parse(jsonLine);
if (exitCode !== 0 && exitCode !== 10) throw new Error(`${STAGE} failed (exit ${exitCode}): ${r.error || 'no error field'}\n--- tail ---\n` + raw.slice(-1200));
return [{ json: { ...r, month: $('Resolve month').first().json.month } }];

const STAGE = '07 Verify';
const raw = ($input.first().json.stdout || '') + '\n' + ($input.first().json.stderr || '');
const lines = raw.trim().split('\n');
const marker = lines.find(l => l.startsWith('__EXIT__'));
const exitCode = marker ? Number(marker.slice(8).trim()) : 0;
const jsonLine = [...lines].reverse().find(l => l.trim().startsWith('{'));
if (!jsonLine) throw new Error(`${STAGE} printed no JSON (exit ${exitCode}).\n--- tail ---\n` + raw.slice(-1200));
const r = JSON.parse(jsonLine);

/* Zero AI attempts is the signature of the call log reaching the joiner as an
   ordinary lookup sheet: accounts, outstanding and recovered all still read
   correctly and only the behavioural half collapses. It cannot be caught by eye,
   so it is caught here. */
const problems = [];
if (r.failedCount) problems.push(`${r.failedCount} book(s) failed to build`);
for (const f of (r.failures || [])) problems.push(`  ${f.check}: ${f.detail}`);
if ((r.zeroAttemptBooks || []).length) problems.push(`ZERO AI ATTEMPTS — do not ship: ${r.zeroAttemptBooks.join(', ')}`);
if ((r.accountMismatch || []).length) problems.push(`account count != book file: ${r.accountMismatch.join(', ')}`);
if ((r.badPdfs || []).length) problems.push(`malformed PDF: ${r.badPdfs.join(', ')}`);
if ((r.gaps || []).length) problems.push(`incomplete (missing status file): ${r.gaps.map(g => `${g.book} day ${g.day}`).join(', ')}`);

return [{ json: { ...r, problems, healthy: problems.length === 0, month: $('Resolve month').first().json.month } }];

