parameters.jsCode:
/* THE MONTH LOCK, WHICH THIS WORKFLOW USED TO RUN WITHOUT.
   rbl-month predates the lock and never took one, so running it — the fallback
   reached for when something is already going wrong — alongside the
   Orchestrator put two writers on one month with nothing to warn either. That
   is the corruption the lock exists to prevent, and it is hardest to unpick
   afterwards. */
const r = $input.first().json;
const repo = $vars.RBL_REPO;
if (!repo) throw new Error('n8n variable RBL_REPO is not set — see n8n/SETUP_MONTH_PIPELINE.md');
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const command = 'cd ' + q(repo)
  + ' && npm run pipeline --silent -- --stage lock --month ' + q(r.month)
  + ' --acquire --run-id ' + q(r.runId)
  + ' --json';
return [{ json: { ...r, command } }];

const r = $('Resolve month').first().json;
const out = $('Acquire the month lock').first().json;

const stdoutRaw = String(out.stdout ?? '');
const sentinelMatch = [...stdoutRaw.matchAll(/^__EXIT__(\d+)\s*$/gm)].pop();
const exitCode = sentinelMatch ? Number(sentinelMatch[1])
  : (Number.isFinite(Number(out.exitCode)) ? Number(out.exitCode) : (out.error ? 1 : 0));
const stdout = stdoutRaw.replace(/^__EXIT__\d+\s*$/gm, '');
const line = stdout.split('\n').map((l) => l.trim()).filter((l) => l.startsWith('{')).pop();
let res = null;
try { res = line ? JSON.parse(line) : null; } catch (e) { res = null; }

if (!(exitCode === 0 && res?.acquired === true)) {
  const h = res?.holder ?? {};
  throw new Error('Month ' + r.month + ' is locked and this run will not start.\n'
    + (res?.reason ?? ('the lock command exited ' + exitCode))
    + (h.runId ? '\n  held by runId ' + h.runId + ' on ' + (h.host ?? '?') + ' (pid ' + (h.pid ?? '?') + ')' : '')
    + '\n  npm run pipeline -- --stage lock --month ' + r.month + ' --status');
}

/* Taking a stale lock is legitimate and must be visible: it means a previous
   run died without releasing. */
return [{ json: { ...r, tookStale: !!res?.tookFrom, lockReason: res?.reason ?? null } }];

const r = $('Resolve month').first().json;
const repo = $vars.RBL_REPO;
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const command = 'cd ' + q(repo)
  + ' && npm run pipeline --silent -- --stage lock --month ' + q(r.month)
  + ' --release --run-id ' + q(r.runId)
  + ' --json';
return [{ json: { ...r, command } }];

